//! Every expectation in this file was produced by the frozen TypeScript
//! prototype, not by the Rust code it checks.
//!
//! `tests/data/global-expected.json` was generated by
//! `tests/oracle/gen-global-expected.ts`, which used the frozen prototype two
//! ways at once.
//!
//! **The fixture is a frozen value: HEAD has no way to regenerate it.** The
//! generator and the prototype it drove were removed with `experiments/` on
//! 2026-08-16 and exist only at tag `experiments-frozen`.
//!
//! # Two oracles, because one of them is blind
//!
//! `cases` run the prototype **as a program** over synthetic IR trees and record
//! the six files it wrote. That was the gate: byte equality with the prototype.
//!
//! **M8-d left one file of the six in place.** Five existed only for doc-gen4's
//! JavaScript, which M8-c replaced, so they are not written any more
//! (`docs/plans/ui-redesign.md` §8 and `lean_doc_global::artifacts`) and the
//! byte comparison below is over the intersection —
//! `declarations/name-map.json`, the one the incremental pipeline reads back as
//! `--before`. The fixture still records all six, and
//! [`the_sample_reaches_every_shape`] still reads the other five out of it: they
//! are the evidence that a curated case reaches a shape, whoever writes the
//! bytes. What this crate writes instead is checked by
//! [`every_case_writes_the_new_artifacts`].
//!
//! [`the_sample_reaches_every_shape`]: the_sample_reaches_every_shape
//! [`every_case_writes_the_new_artifacts`]: every_case_writes_the_new_artifacts
//!
//! `factCases` call `factsOf` / `autolinkTokens` / `headConst` **sliced out of
//! the same file**. [`lean_doc_global::ModuleFacts::tokens`] reaches no
//! artifact — it is the whole-package map delta's input, which is M2-b — so a
//! port that dropped tokens entirely would pass every byte comparison in the
//! first oracle. This one sees it.
//!
//! # What this file does **not** stand on
//!
//! The real corpus. That is [`artifacts_match_the_reference`] and
//! [`corpus_facts_match_the_prototype`], both `#[ignore]`d because the corpus
//! is not in this repository, and `tools/global-compare.sh`. The curated cases
//! exist to reach the corners the corpus has none of.
//!
//! # Fourteen of the thirty-seven branches never fire on the real corpus
//!
//! 【実測, `branchTotals`】 — among them every branch U1 depends on. The target
//! package has no name above the BMP anywhere: not one of 4,750 declarations,
//! not one of 533 dependency names, not one of 432 module names. All seven of
//! the prototype's argument-less `.sort()` calls therefore agree with a UTF-8
//! sort on all 1.9 MB of real output, and the only thing that says otherwise is
//! [`Case`] "names above the BMP".

use std::collections::{BTreeMap, BTreeSet};
use std::fs;
use std::path::PathBuf;

use lean_doc_global::{ARTIFACT_PATHS, GlobalOptions, ModuleFacts, State, build_global, facts_for};
use lean_doc_ir::IrTree;
use serde::{Deserialize, Serialize};

const FIXTURE: &str = include_str!("data/global-expected.json");

const DEFAULT_IR: &str = "/private/tmp/lean-doc-relay/w7h/base-ir";
const DEFAULT_REFERENCE: &str = "/private/tmp/lean-doc-relay/m2/ref-global";

#[derive(Deserialize)]
#[serde(rename_all = "camelCase")]
struct Expected {
    oracle: String,
    ir_modules: usize,
    ir_declarations: usize,
    corpus_facts: CorpusFacts,
    /// `None` when the fixture was generated on a machine with no reference
    /// tree. Committed as `Some`.
    reference: Option<BTreeMap<String, Digest>>,
    /// How often each branch fires in one full run of the target package.
    branch_totals: BTreeMap<String, u64>,
    /// How many curated cases — of either kind — reach each branch.
    curated_branches: BTreeMap<String, u64>,
    /// The branches with a zero in `branch_totals`, as the generator listed
    /// them. Stored as well as derivable so a disagreement is itself a failure.
    never_fires: BTreeSet<String>,
    cases: Vec<Case>,
    fact_cases: Vec<FactCase>,
}

#[derive(Deserialize)]
#[serde(rename_all = "camelCase")]
struct CorpusFacts {
    modules: usize,
    bytes: usize,
    tokens: usize,
    fnv1a64: String,
    /// Module docstrings carrying the `doc` key `global.ts:152` reads. **Zero**,
    /// which is why the module docstring branch is dead — see
    /// [`module_docstrings_are_never_tokenised`].
    module_docs_with_doc_key: usize,
}

#[derive(Deserialize)]
#[serde(rename_all = "camelCase")]
struct Digest {
    bytes: usize,
    fnv1a64: String,
}

#[derive(Deserialize)]
#[serde(rename_all = "camelCase")]
struct Case {
    what: String,
    /// The counters this case's own IR makes fire, as the generator's profile
    /// function counted them.
    branches: Vec<String>,
    /// The IR tree as bytes, keyed by path under its root.
    ir: BTreeMap<String, String>,
    /// The six files the prototype wrote, keyed by path under the site root.
    /// Five of them have no counterpart here any more — see the module heading.
    artifacts: BTreeMap<String, String>,
}

#[derive(Deserialize)]
#[serde(rename_all = "camelCase")]
struct FactCase {
    what: String,
    branches: Vec<String>,
    note: Option<String>,
    content_hash: String,
    /// One module file, exactly as the prototype was handed it.
    module: String,
    facts: Facts,
}

/// [`ModuleFacts`] on the wire, in the key order `factsOf` returns it in. Also
/// what [`corpus_facts_match_the_prototype`] re-serialises to compare digests,
/// so the field order is load-bearing.
#[derive(Debug, Deserialize, Serialize, PartialEq, Eq)]
#[serde(rename_all = "camelCase")]
struct Facts {
    module: String,
    content_hash: String,
    imports: Vec<String>,
    tactics: usize,
    decls: Vec<(String, String)>,
    instances: Vec<(String, String)>,
    tokens: Vec<String>,
}

impl From<&ModuleFacts> for Facts {
    fn from(facts: &ModuleFacts) -> Self {
        Self {
            module: facts.module.clone(),
            content_hash: facts.content_hash.clone(),
            imports: facts.imports.clone(),
            tactics: facts.tactics,
            decls: facts.decls.clone(),
            instances: facts.instances.clone(),
            tokens: facts.tokens.clone(),
        }
    }
}

fn expected() -> Expected {
    serde_json::from_str(FIXTURE).expect("tests/data/global-expected.json is valid")
}

#[test]
fn fixture_is_the_prototypes_own_output() {
    let e = expected();
    assert!(e.oracle.contains("global.ts"), "{}", e.oracle);
    assert!(e.oracle.contains("run as a program"), "{}", e.oracle);
    assert!(e.oracle.contains("sliced out"), "{}", e.oracle);
    assert!(e.cases.len() >= 8, "only {} artifact cases", e.cases.len());
    assert!(
        e.fact_cases.len() >= 4,
        "only {} fact cases",
        e.fact_cases.len()
    );
}

/// The comparison this file exists for, over what is left of it: every
/// artifact this crate **and** the prototype write, byte for byte.
///
/// That intersection is one file. It is also the one whose bytes another
/// program reads back — `--before`, the whole-package map delta — so it is the
/// one where a disagreement with the prototype would still mean something.
#[test]
fn every_case_reproduces_the_prototypes_artifacts() {
    let e = expected();
    let shared: Vec<&str> = ARTIFACT_PATHS
        .iter()
        .copied()
        .filter(|path| {
            e.cases
                .iter()
                .all(|case| case.artifacts.contains_key(*path))
        })
        .collect();
    assert_eq!(
        shared,
        ["declarations/name-map.json"],
        "which artifacts the prototype and this crate both write has changed"
    );

    let mut failures = Vec::new();
    let mut compared = 0usize;
    for case in &e.cases {
        let work = TempDir::new(&case.what);
        let got = case.build(&work);
        let want: BTreeMap<String, String> = shared
            .iter()
            .map(|path| ((*path).to_owned(), case.artifacts[*path].clone()))
            .collect();
        let mine: BTreeMap<String, String> = shared
            .iter()
            .map(|path| {
                let body = got
                    .get(*path)
                    .unwrap_or_else(|| panic!("{}: {path} was not written", case.what));
                ((*path).to_owned(), body.clone())
            })
            .collect();
        if mine != want {
            failures.push(describe(&case.what, &want, &mine));
        }
        compared += want.len();
    }
    assert!(
        failures.is_empty(),
        "{} of {} cases differ from the prototype:\n{}",
        failures.len(),
        e.cases.len(),
        failures.join("\n")
    );
    assert_eq!(compared, e.cases.len() * shared.len());
}

/// The other side of the same run: every case writes all seven artifacts, and
/// none of the five M8-d dropped.
///
/// The dropped five are named rather than counted 【判断】: "seven files came
/// out" would still pass if `navbar.html` came back and something else went, and
/// what §8 decided was which files, not how many.
#[test]
fn every_case_writes_the_new_artifacts() {
    let e = expected();
    for case in &e.cases {
        let work = TempDir::new(&case.what);
        let got = case.build(&work);
        let written: Vec<&String> = got.keys().collect();
        let mut want: Vec<&str> = ARTIFACT_PATHS.to_vec();
        want.sort_unstable();
        assert_eq!(
            written, want,
            "{}: the site tree is not the seven artifacts",
            case.what
        );
        for dropped in [
            "declarations/declaration-data.bmp",
            "navbar.html",
            "tactics.html",
            "references.bib",
            "references.html",
        ] {
            assert!(
                !got.contains_key(dropped),
                "{}: {dropped} is being written again",
                case.what
            );
        }
    }
}

/// The two JSON indexes, as `assets/app.js` reads them, over the curated cases
/// rather than over a hand-built package.
///
/// The unit tests in `src/artifacts.rs` pin the shape on three modules this
/// file can see the source of; this pins it on the eight IR trees the prototype
/// was run over, including the ones with names above the BMP and names that
/// need escaping.
#[test]
fn the_indexes_are_well_formed_in_every_case() {
    let e = expected();
    for case in &e.cases {
        let work = TempDir::new(&case.what);
        let got = case.build(&work);
        let read = |path: &str| -> serde_json::Value {
            serde_json::from_str(&got[path])
                .unwrap_or_else(|err| panic!("{}: {path}: {err}", case.what))
        };

        let modules = read("modules.json");
        let list = modules["modules"].as_array().expect("an array of modules");
        for module in list {
            assert!(
                module["n"].is_string() && module["p"].is_string(),
                "{}",
                case.what
            );
            for at in module["i"].as_array().expect("an array of subscripts") {
                let at = usize::try_from(at.as_u64().expect("a subscript")).expect("fits");
                assert!(
                    at < list.len(),
                    "{}: a subscript points past the array",
                    case.what
                );
            }
        }

        let index = read("search-index.json");
        let indexed = index["modules"].as_array().expect("modules");
        let kinds = index["kinds"].as_array().expect("kinds");
        assert_eq!(
            indexed.len(),
            list.len(),
            "{}: the two files disagree about how many modules there are",
            case.what
        );
        for (a, b) in list.iter().zip(indexed) {
            assert_eq!(
                a["n"], b["n"],
                "{}: the two module arrays are not one order",
                case.what
            );
            assert_eq!(a["p"], b["p"], "{}", case.what);
        }
        for decl in index["decls"].as_array().expect("decls") {
            let row = decl.as_array().expect("a triple");
            assert_eq!(row.len(), 3, "{}", case.what);
            assert!(row[0].is_string(), "{}", case.what);
            let kind = usize::try_from(row[1].as_u64().expect("a kind index")).expect("fits");
            let module = usize::try_from(row[2].as_u64().expect("a module index")).expect("fits");
            assert!(
                kind < kinds.len() && module < indexed.len(),
                "{}",
                case.what
            );
        }
        for key in ["instances", "instancesFor"] {
            for (_, names) in index[key].as_object().expect("a map of name lists") {
                assert!(
                    names
                        .as_array()
                        .is_some_and(|names| names.iter().all(serde_json::Value::is_string)),
                    "{}: {key} is not a map of string arrays",
                    case.what
                );
            }
        }
    }
}

/// The other oracle: the per-module facts, including the tokens no artifact
/// carries.
#[test]
fn every_fact_case_reproduces_the_prototypes_facts() {
    let e = expected();
    for case in &e.fact_cases {
        let module: lean_doc_ir::ModuleFile = serde_json::from_str(&case.module)
            .unwrap_or_else(|e| panic!("{}: the module file parses: {e}", case.what));
        let got = Facts::from(&ModuleFacts::of(&module, &case.content_hash));
        assert_eq!(got, case.facts, "{}", case.what);
    }
}

/// The branch plan §5 says to transcribe rather than fix, pinned from both
/// sides: the corpus has no module docstring with the key the prototype reads,
/// and a curated module docstring full of linkable names still yields none.
#[test]
fn module_docstrings_are_never_tokenised() {
    let e = expected();
    assert_eq!(
        e.corpus_facts.module_docs_with_doc_key, 0,
        "a module docstring now carries the `doc` key `global.ts:152` reads; the transcription \
         in ModuleFacts::of is no longer a dead branch and the plan's §5 M2 entry is stale"
    );

    let case = e
        .fact_cases
        .iter()
        .find(|c| c.what.contains("module docstring"))
        .expect("a fact case covers the module docstring branch");
    let module: lean_doc_ir::ModuleFile =
        serde_json::from_str(&case.module).expect("the module file parses");
    assert!(
        module.module_docs.len() >= 2,
        "the case has to have module docstrings for their absence to mean anything"
    );
    assert!(
        module
            .module_docs
            .iter()
            .any(|doc| doc.text.contains('`') && doc.text.contains("](")),
        "the case's module docstrings have to contain names a fixed version would harvest"
    );
    let facts = ModuleFacts::of(&module, &case.content_hash);
    for token in &facts.tokens {
        assert!(
            !token.starts_with("Mod."),
            "{token:?} came from a module docstring: the transcription was 'fixed'"
        );
    }
    assert_eq!(facts.tokens, case.facts.tokens);
}

/// What the corpus is, pinned so a number quoted elsewhere traces to a run of
/// the generator rather than to a memory of one.
///
/// Every count is an event of **one full run** of the target package.
#[test]
fn the_corpus_numbers_are_what_was_measured() {
    let e = expected();
    assert_eq!(e.ir_modules, 432);
    assert_eq!(e.ir_declarations, 4_750);
    assert_eq!(
        e.branch_totals,
        BTreeMap::from(
            [
                // the facts
                ("moduleFacts", 432),
                ("moduleWithTactics", 0),
                ("tacticDocs", 0),
                ("moduleWithoutImports", 0),
                ("importOwn", 2_031),
                ("importForeign", 1_904),
                ("moduleDocDropped", 1_515),
                ("moduleDocWithCodeSpan", 759),
                ("declFacts", 4_750),
                ("declWithDoc", 3_394),
                ("declWithoutDoc", 1_356),
                ("declWithEmptyDoc", 0),
                ("docWithCodeSpan", 3_057),
                ("docWithLinkTarget", 1),
                ("tokensTotal", 21_825),
                ("tokenWithDot", 1_295),
                ("tokenEmptyString", 16),
                ("instanceDecl", 91),
                ("instanceWithHeadConst", 91),
                ("instanceWithoutHeadConst", 0),
                ("instanceHeadNotFirstSpan", 0),
                ("namedNonConstSpan", 0),
                // the derivation
                ("nameMapOverwrite", 0),
                ("instanceClassFirstSeen", 9),
                ("instanceClassAgain", 82),
                ("moduleImportedByNone", 1),
                ("depMapFiles", 3),
                ("depMapEntries", 533),
                ("depNameAlsoDeclared", 0),
                ("depNameOnly", 533),
                ("topLevelPagePath", 1),
                ("nestedPagePath", 431),
                ("moduleNameNeedsEscaping", 0),
                ("nameAboveBmp", 0),
                ("moduleNameAboveBmp", 0),
                ("runWithoutModules", 0),
                ("runWithoutDepMaps", 0),
            ]
            .map(|(k, n)| (k.to_owned(), n))
        ),
        "the branch profile of the corpus changed"
    );

    // Cross-checks between counters that have to agree by construction.
    assert_eq!(
        e.branch_totals["declWithDoc"] + e.branch_totals["declWithoutDoc"],
        e.ir_declarations as u64
    );
    assert_eq!(
        e.branch_totals["topLevelPagePath"] + e.branch_totals["nestedPagePath"],
        e.ir_modules as u64,
        "every module's page goes somewhere"
    );
    assert_eq!(
        e.branch_totals["instanceWithHeadConst"] + e.branch_totals["instanceWithoutHeadConst"],
        e.branch_totals["instanceDecl"]
    );
    assert_eq!(
        e.branch_totals["instanceClassFirstSeen"] + e.branch_totals["instanceClassAgain"],
        e.branch_totals["instanceWithHeadConst"],
        "every recorded instance lands under a class"
    );
    assert_eq!(
        e.branch_totals["depNameAlsoDeclared"] + e.branch_totals["depNameOnly"],
        e.branch_totals["depMapEntries"]
    );
    assert_eq!(e.corpus_facts.modules, e.ir_modules);
    assert_eq!(
        e.corpus_facts.tokens as u64, e.branch_totals["tokensTotal"],
        "the digest and the profile were taken from different runs"
    );
    // `a.` really does occur: 16 tokens of the corpus are the empty string,
    // which only `push`'s unconditional last component can produce.
    assert!(e.branch_totals["tokenEmptyString"] > 0);
}

/// The fourteen branches no module of the target package reaches, and the fact
/// that the curated cases do reach them.
#[test]
fn the_curated_cases_cover_what_the_package_does_not() {
    let e = expected();
    let never: BTreeSet<String> = e
        .branch_totals
        .iter()
        .filter(|(_, n)| **n == 0)
        .map(|(k, _)| k.clone())
        .collect();
    assert_eq!(
        never, e.never_fires,
        "the generator and the totals disagree about which branches are dead"
    );
    assert_eq!(
        never,
        BTreeSet::from(
            [
                // U1. Not one name in the package is above the BMP, so a UTF-8
                // sort in any of the seven places is invisible to all 1.9 MB.
                "nameAboveBmp",
                "moduleNameAboveBmp",
                // The package declares no tactics, so `tactics.html`'s first
                // count is always the literal it looks like.
                "moduleWithTactics",
                "tacticDocs",
                // Every instance's printed type has a constant span, and it is
                // always the first one in the array.
                "instanceWithoutHeadConst",
                "instanceHeadNotFirstSpan",
                // The extractor names kind-1 spans and nothing else, so
                // `head_const`'s kind test is load-bearing only in theory.
                "namedNonConstSpan",
                // Every name is declared once, and no dependency slice names
                // something the package declares.
                "nameMapOverwrite",
                "depNameAlsoDeclared",
                // Shapes the extractor never produced here.
                "moduleWithoutImports",
                "moduleNameNeedsEscaping",
                "declWithEmptyDoc",
                // Degenerate runs.
                "runWithoutModules",
                "runWithoutDepMaps",
            ]
            .map(str::to_owned)
        ),
        "which branches the target package never reaches has changed"
    );
    for branch in &never {
        assert!(
            e.curated_branches.get(branch).copied().unwrap_or(0) > 0,
            "{branch} fires nowhere in the corpus and nowhere in the curated cases either"
        );
    }
    let all: BTreeSet<&String> = e.branch_totals.keys().collect();
    let curated: BTreeSet<&String> = e
        .curated_branches
        .iter()
        .filter(|(_, n)| **n > 0)
        .map(|(k, _)| k)
        .collect();
    assert_eq!(all, curated, "the curated cases stopped covering a branch");

    // `curatedBranches` is a tally of the per-case lists, so recompute it: a
    // summary that is not what it summarises is how a coverage claim rots.
    let mut tally: BTreeMap<String, u64> = BTreeMap::new();
    let per_case = e
        .cases
        .iter()
        .map(|case| &case.branches)
        .chain(e.fact_cases.iter().map(|case| &case.branches));
    for branches in per_case {
        for branch in branches {
            assert!(
                e.branch_totals.contains_key(branch),
                "case claims {branch}, which is not a counter"
            );
            *tally.entry(branch.clone()).or_default() += 1;
        }
    }
    assert_eq!(
        tally, e.curated_branches,
        "the tally and the per-case lists disagree"
    );
}

/// The sample has to keep reaching every shape, read off the **fixture's own
/// bytes** — which came from the prototype — rather than off anything this
/// crate produced.
///
/// Four of the five files read here are ones M8-d stopped writing, and they are
/// still the right place to ask this question: what is under test is whether
/// the **curated IR trees** reach a shape, and the prototype's output over those
/// trees is the record of it. The same shapes are asked of this crate's own
/// output by [`the_new_artifacts_reach_every_shape`].
///
/// The paths are spelled out rather than taken from `ARTIFACT_PATHS`, which no
/// longer contains four of them.
///
/// [`the_new_artifacts_reach_every_shape`]: the_new_artifacts_reach_every_shape
#[test]
fn the_sample_reaches_every_shape() {
    let e = expected();
    let bmp = |what: &str, p: &dyn Fn(&str) -> bool| {
        any_artifact(&e.cases, "declarations/declaration-data.bmp", what, p);
    };
    let names = |what: &str, p: &dyn Fn(&str) -> bool| {
        any_artifact(&e.cases, "declarations/name-map.json", what, p);
    };
    let navbar = |what: &str, p: &dyn Fn(&str) -> bool| {
        any_artifact(&e.cases, "navbar.html", what, p);
    };
    let tactics = |what: &str, p: &dyn Fn(&str) -> bool| {
        any_artifact(&e.cases, "tactics.html", what, p);
    };

    // U1: 𝒜 (U+1D49C) has to come out **before** ﬀ (U+FB00) everywhere.
    let astral_first = |body: &str| match (body.find('\u{1D49C}'), body.find('\u{FB00}')) {
        (Some(astral), Some(ligature)) => astral < ligature,
        _ => false,
    };
    bmp(
        "a name above the BMP sorted before one inside it",
        &astral_first,
    );
    names(
        "a name above the BMP sorted before one inside it",
        &astral_first,
    );
    navbar(
        "a module name above the BMP sorted before one inside it",
        &astral_first,
    );

    bmp("no declarations at all", &|body| {
        body.starts_with("{\"declarations\":{},")
    });
    bmp("an instance list", &|body| {
        body.contains("\"instances\":{\"Cls.B\":[\"Pkg.Inst.alsoB\",\"Pkg.Inst.reordered\"]")
    });
    bmp("an instance dropped for want of a head constant", &|body| {
        body.contains("Pkg.Inst.noConst") && !body.contains("[\"Pkg.Inst.noConst\"]")
    });
    bmp("an importedBy list", &|body| {
        body.contains("\"importedBy\":[\"Pkg.Deep.Down.Here\"]")
    });
    bmp("a duplicated name resolved to the later module", &|body| {
        body.contains(
            "\"Pkg.shared\":{\"docLink\":\"./Pkg/Second.html#Pkg.shared\",\"kind\":\"def\"}",
        )
    });
    names("a declaration beating a dependency slice", &|body| {
        body.contains("\"Shared.name\":\"Pkg.One\"")
    });
    names("a later dependency slice beating an earlier one", &|body| {
        body.contains("\"Dep.only\":\"Dep2.Wins\"")
    });
    // The apostrophe stays raw: `Html.escape` does not touch it, and every
    // general-purpose HTML escaper does.
    navbar("a module name that needs escaping", &|body| {
        body.contains(
            "<li><a href=\"./Pkg/A&lt;B&amp;C&quot;D'E.html\">Pkg.A&lt;B&amp;C&quot;D'E</a></li>",
        )
    });
    navbar("no modules at all", &|body| body.contains("<ul></ul>"));
    tactics("a package that declares tactics", &|body| {
        body.contains("(3 tactic docstrings across 3 modules)")
    });
    tactics("no modules at all", &|body| {
        body.contains("(0 tactic docstrings across 0 modules)")
    });

    // The fact cases' own corners.
    let tokens: Vec<&String> = e
        .fact_cases
        .iter()
        .flat_map(|c| c.facts.tokens.iter())
        .collect();
    assert!(
        tokens.iter().any(|t| t.is_empty()),
        "no fact case has the empty token a part ending in a dot produces"
    );
    assert!(
        tokens.iter().any(|t| *t == "Bar.baz"),
        "no fact case tokenises a markdown link target"
    );
    assert!(
        e.fact_cases.iter().any(|c| c.note.is_some()),
        "the recorded disagreement lost its note"
    );
}

/// The same corners, on **this crate's own output**: the shapes the curated
/// cases exist for have to survive the change of file format, not only the
/// change of file list.
///
/// The prototype's four files carried these shapes in HTML and in a JSON object
/// keyed by module; here they are in a JSON array of modules and in
/// `index.html`. A case that reaches a shape and an artifact that does nothing
/// with it is the failure this pins.
#[test]
fn the_new_artifacts_reach_every_shape() {
    let e = expected();
    let mut astral = 0usize;
    let mut escaped = 0usize;
    let mut empty = 0usize;
    let mut instances = 0usize;
    let mut imported_by = 0usize;

    for case in &e.cases {
        let work = TempDir::new(&case.what);
        let got = case.build(&work);
        let modules: serde_json::Value =
            serde_json::from_str(&got["modules.json"]).expect("modules.json is JSON");
        let index: serde_json::Value =
            serde_json::from_str(&got["search-index.json"]).expect("search-index.json is JSON");
        let names: Vec<&str> = modules["modules"]
            .as_array()
            .expect("modules")
            .iter()
            .map(|m| m["n"].as_str().expect("a name"))
            .collect();
        let front = &got["index.html"];

        // U1: `𝒜` (U+1D49C) sorts *below* `ﬀ` (U+FB00) in UTF-16 and above it
        // by code point, in the array and on the page alike.
        let order = |body: &str| match (body.find('\u{1D49C}'), body.find('\u{FB00}')) {
            (Some(a), Some(b)) => Some(a < b),
            _ => None,
        };
        for body in [&got["modules.json"], &got["search-index.json"], front] {
            if let Some(first) = order(body) {
                assert!(first, "a name above the BMP did not sort first: {body}");
                astral += 1;
            }
        }
        // `Html.escape` covers `& < > "` and leaves `'` alone, and the module
        // list on the front page is HTML while the two indexes are not.
        if names.iter().any(|n| n.contains('<')) {
            assert!(
                front.contains("&lt;") && front.contains("&amp;") && front.contains("&quot;"),
                "a module name that needs escaping reached index.html raw: {front}"
            );
            escaped += 1;
        }
        if names.is_empty() {
            assert!(
                front.contains("<ul class=\"modlist\"></ul>"),
                "a package with no modules did not produce an empty list: {front}"
            );
            assert_eq!(index["decls"], serde_json::json!([]));
            empty += 1;
        }
        if index["instances"]
            .as_object()
            .is_some_and(|map| !map.is_empty())
        {
            instances += 1;
        }
        if modules["modules"]
            .as_array()
            .expect("modules")
            .iter()
            .any(|m| !m["i"].as_array().expect("subscripts").is_empty())
        {
            imported_by += 1;
        }
    }

    for (what, seen) in [
        ("a name above the BMP", astral),
        ("a module name that needs escaping", escaped),
        ("a package with no modules", empty),
        ("an instance list", instances),
        ("an importer list", imported_by),
    ] {
        assert!(seen > 0, "no case reaches {what} in the new artifacts");
    }
}

/// This crate's URL-path rule and the renderer's filesystem one have to be the
/// same rule: `declaration-data.bmp` links to pages the renderer wrote, and a
/// disagreement is 4,750 dead links that no byte comparison of either side
/// notices.
#[test]
fn page_paths_agree_with_the_renderers() {
    for module in [
        "Pkg",
        "Pkg.One",
        "Pkg.A.B.C.D",
        "InformationTheory.Shannon.TimeBandLimiting.Count",
        "Pkg.\u{1D49C}",
        "Pkg.A<B&C\"D",
    ] {
        assert_eq!(
            lean_doc_global::page_path(module),
            lean_doc_render::page_path(module).to_string_lossy(),
            "{module}"
        );
    }
}

/// The sizes the committed fixture records for the reference tree's six files,
/// pinned **whether or not the corpus is on this machine**, so the numbers in
/// the report have a home.
///
/// Split out of [`artifacts_match_the_reference`], which needs the reference
/// tree and is therefore `#[ignore]`d: these numbers are what
/// `docs/plans/ui-redesign.md` §8 quotes when it says what M8-d deleted, and
/// they have to keep being checked on a machine that has never seen the target
/// package.
///
/// [`artifacts_match_the_reference`]: artifacts_match_the_reference
#[test]
fn the_recorded_reference_sizes_are_pinned_without_the_corpus() {
    let e = expected();
    let recorded = e
        .reference
        .as_ref()
        .expect("the committed fixture pins the real artifacts");
    assert_eq!(
        recorded["declarations/declaration-data.bmp"].bytes,
        1_216_017
    );
    assert_eq!(recorded["declarations/name-map.json"].bytes, 602_729);
    assert_eq!(recorded["navbar.html"].bytes, 57_949);
    assert_eq!(recorded["tactics.html"].bytes, 243);
    assert_eq!(recorded["references.bib"].bytes, 0);
    assert_eq!(recorded["references.html"].bytes, 186);
}

/// The artifacts of the target package that the prototype also writes —
/// `declarations/name-map.json`, and since M8-d only that — against the files
/// it wrote.
///
/// The same comparison `tools/global-compare.sh` makes, over what is left of
/// it. Asserting the recorded size of each file first is what says the
/// reference tree on this machine is still the one the fixture came from; the
/// same numbers are pinned without the corpus by
/// [`the_recorded_reference_sizes_are_pinned_without_the_corpus`].
///
/// [`the_recorded_reference_sizes_are_pinned_without_the_corpus`]: the_recorded_reference_sizes_are_pinned_without_the_corpus
#[test]
#[ignore = "corpus: needs LEAN_DOC_REFERENCE_GLOBAL + LEAN_DOC_IR (tools/corpus-gate.sh)"]
fn artifacts_match_the_reference() {
    let e = expected();
    let recorded = e
        .reference
        .as_ref()
        .expect("the committed fixture pins the real artifacts");
    let reference = corpus_reference();
    let ir = corpus_ir();

    let work = TempDir::new("reference");
    let summary = build_global(&GlobalOptions::new(&ir, &work.path)).expect("the corpus builds");
    assert_eq!(summary.modules, e.ir_modules);
    assert_eq!(summary.declarations, e.ir_declarations);
    assert_eq!(
        summary.dependency_names as u64,
        e.branch_totals["depMapEntries"]
    );
    assert_eq!(
        summary.instance_classes as u64,
        e.branch_totals["instanceClassFirstSeen"]
    );
    assert_eq!(summary.tactic_docs, 0);
    // UI-V5 【実測 2026-08-16】: the 91 instances of this package name 88
    // distinct types between them, and each of the 59 that doc-gen4's own
    // reference tree also has agrees with its `instancesFor` entry exactly. The
    // other 32 are in the 43 modules the reference tree predates.
    assert_eq!(summary.instance_types, 88);

    let shared = ["declarations/name-map.json"];
    assert!(
        shared.iter().all(|path| ARTIFACT_PATHS.contains(path)),
        "the shared artifact is not one this crate writes"
    );
    for path in shared {
        let want = fs::read(reference.join(path)).expect("the reference artifact reads");
        let got = fs::read(work.path.join(path)).expect("the artifact was written");
        assert_eq!(
            recorded[path].bytes,
            want.len(),
            "{path}: the reference tree is not the one the fixture was taken from"
        );
        assert_eq!(fnv1a64(&want), recorded[path].fnv1a64, "{path}");
        assert_eq!(
            got.len(),
            want.len(),
            "{path}: {} bytes against the prototype's {}",
            got.len(),
            want.len()
        );
        assert!(
            got == want,
            "{path} differs from the prototype at byte {}",
            got.iter()
                .zip(&want)
                .position(|(a, b)| a != b)
                .unwrap_or(got.len())
        );
    }
}

/// The per-module facts over the whole corpus, against the prototype's own
/// `factsOf`.
///
/// This is what checks [`ModuleFacts::tokens`] on 3,394 real docstrings rather
/// than on four curated ones. The digest is FNV-1a 64 over the same canonical
/// JSON both sides emit; the two counts beside it are what a digest cannot say
/// when it disagrees.
#[test]
#[ignore = "corpus: needs LEAN_DOC_IR (tools/corpus-gate.sh)"]
fn corpus_facts_match_the_prototype() {
    let e = expected();
    let ir = corpus_ir();
    let tree = IrTree::open(&ir).expect("the corpus opens");
    // No cache: this is the from-scratch read, so every module is a miss.
    let run = facts_for(&tree, &State::empty()).expect("the corpus reads");
    let facts = run.facts;
    assert_eq!(facts.len(), e.corpus_facts.modules);
    assert_eq!(run.cache_hits, 0);
    assert_eq!(run.cache_misses, facts.len());

    let lines: Vec<String> = facts
        .iter()
        .map(|facts| serde_json::to_string(&Facts::from(facts)).expect("the facts serialise"))
        .collect();
    let text = lines.join("\n");
    let tokens: usize = facts.iter().map(|facts| facts.tokens.len()).sum();
    assert_eq!(tokens, e.corpus_facts.tokens, "the token count moved");
    assert_eq!(
        text.len(),
        e.corpus_facts.bytes,
        "the serialised facts are a different size than the prototype's"
    );
    assert_eq!(
        fnv1a64(text.as_bytes()),
        e.corpus_facts.fnv1a64,
        "the facts differ from the prototype's somewhere in {} bytes",
        text.len()
    );
}

// ------------------------------------------------------------------- helpers

/// The generated IR of the target package, or a panic naming what to set.
///
/// Every caller is `#[ignore]`d, so reaching this function at all means the
/// corpus gate asked for the test by name. Returning "not here, never mind"
/// there would be a green result for a comparison that never ran.
fn corpus_ir() -> PathBuf {
    let ir = PathBuf::from(std::env::var("LEAN_DOC_IR").unwrap_or_else(|_| DEFAULT_IR.into()));
    assert!(
        ir.is_dir(),
        "no IR tree at {}: set LEAN_DOC_IR, or run this test through tools/corpus-gate.sh, \
         which is the only thing that should be asking for it",
        ir.display()
    );
    ir
}

/// The reference tree the frozen prototype wrote, or a panic naming what to set.
fn corpus_reference() -> PathBuf {
    let reference = PathBuf::from(
        std::env::var("LEAN_DOC_REFERENCE_GLOBAL").unwrap_or_else(|_| DEFAULT_REFERENCE.into()),
    );
    assert!(
        reference.is_dir(),
        "no reference tree at {}: set LEAN_DOC_REFERENCE_GLOBAL, or run this test through \
         tools/corpus-gate.sh, which is the only thing that should be asking for it",
        reference.display()
    );
    reference
}

/// At least one case's copy of `path` satisfies `predicate`.
fn any_artifact(cases: &[Case], path: &str, what: &str, predicate: &dyn Fn(&str) -> bool) {
    assert!(
        cases
            .iter()
            .filter_map(|case| case.artifacts.get(path))
            .any(|body| predicate(body)),
        "no {path} with {what}"
    );
}

impl Case {
    /// Writes the case's IR into `work`, builds the artifacts, and reads **the
    /// whole site tree** back.
    ///
    /// The whole tree rather than [`ARTIFACT_PATHS`]: a file this crate stopped
    /// writing has to be absent, and a list of the files it does write cannot
    /// tell the difference between "gone" and "never looked for".
    fn build(&self, work: &TempDir) -> BTreeMap<String, String> {
        let ir = work.path.join("ir");
        for (name, text) in &self.ir {
            let path = ir.join(name);
            fs::create_dir_all(path.parent().expect("every IR file is under the root"))
                .expect("the temporary tree is writable");
            fs::write(&path, text).expect("the temporary tree is writable");
        }
        let site = work.path.join("site");
        build_global(&GlobalOptions::new(&ir, &site))
            .unwrap_or_else(|e| panic!("{}: {e}", self.what));

        let mut out = BTreeMap::new();
        read_tree(&site, "", &mut out);
        out
    }
}

/// Every file under `dir`, keyed by its `/`-separated path beneath it.
fn read_tree(dir: &PathBuf, prefix: &str, out: &mut BTreeMap<String, String>) {
    for entry in fs::read_dir(dir)
        .expect("the site tree is readable")
        .flatten()
    {
        let name = entry.file_name().to_string_lossy().into_owned();
        let relative = if prefix.is_empty() {
            name
        } else {
            format!("{prefix}/{name}")
        };
        if entry.file_type().expect("a file type").is_dir() {
            read_tree(&entry.path(), &relative, out);
        } else {
            out.insert(
                relative,
                fs::read_to_string(entry.path()).expect("the artifact is UTF-8"),
            );
        }
    }
}

/// FNV-1a 64, the same ten lines the generator has. A staleness check, not a
/// security property.
fn fnv1a64(bytes: &[u8]) -> String {
    let mut hash: u64 = 0xcbf2_9ce4_8422_2325;
    for byte in bytes {
        hash = (hash ^ u64::from(*byte)).wrapping_mul(0x0000_0100_0000_01b3);
    }
    format!("{hash:016x}")
}

fn describe(what: &str, want: &BTreeMap<String, String>, got: &BTreeMap<String, String>) -> String {
    let mut lines = vec![what.to_owned()];
    // The `collect` is not needless: `chain` yields a path present in both maps
    // twice, and this is the message a failing assertion prints. Iterating the
    // chain directly reports every shared path a second time.
    #[expect(clippy::needless_collect, reason = "deduplicates the two key sets")]
    for path in want.keys().chain(got.keys()).collect::<BTreeSet<_>>() {
        match (want.get(path), got.get(path)) {
            (Some(a), Some(b)) if a == b => {}
            (Some(a), Some(b)) => {
                let at = a
                    .bytes()
                    .zip(b.bytes())
                    .position(|(x, y)| x != y)
                    .unwrap_or_else(|| a.len().min(b.len()));
                let from = at.saturating_sub(80);
                lines.push(format!(
                    "  {path} differs at byte {at}\n    want: …{}\n    got:  …{}",
                    &a[floor_char(a, from)..floor_char(a, (at + 120).min(a.len()))],
                    &b[floor_char(b, from)..floor_char(b, (at + 120).min(b.len()))],
                ));
            }
            (Some(_), None) => lines.push(format!("  {path} was not written")),
            (None, Some(_)) => lines.push(format!("  {path} should not exist")),
            (None, None) => unreachable!(),
        }
    }
    lines.join("\n")
}

/// The nearest char boundary at or below `at`, so slicing an artifact for a
/// failure message cannot itself panic.
fn floor_char(s: &str, mut at: usize) -> usize {
    while at > 0 && !s.is_char_boundary(at) {
        at -= 1;
    }
    at
}

/// A directory that removes itself. Hand-rolled rather than a dependency: it is
/// ten lines and the workspace has no other use for one.
struct TempDir {
    path: PathBuf,
}

impl TempDir {
    fn new(what: &str) -> Self {
        use std::sync::atomic::{AtomicU32, Ordering};
        static NEXT: AtomicU32 = AtomicU32::new(0);
        let slug: String = what
            .chars()
            .map(|c| if c.is_ascii_alphanumeric() { c } else { '-' })
            .take(40)
            .collect();
        let path = std::env::temp_dir().join(format!(
            "lean-doc-global-{}-{}-{slug}",
            std::process::id(),
            NEXT.fetch_add(1, Ordering::Relaxed)
        ));
        let _ = fs::remove_dir_all(&path);
        fs::create_dir_all(&path).expect("the temporary directory is creatable");
        Self { path }
    }
}

impl Drop for TempDir {
    fn drop(&mut self) {
        let _ = fs::remove_dir_all(&self.path);
    }
}
